  readonly context=inject(ContextService);readonly dialog=inject(MatDialogRef<InviteDialogComponent>);private readonly api=inject(ApiService);readonly error=signal('');readonly saving=signal(false);email='';role:'ADMIN'|'MEMBER'='MEMBER';
  async save():Promise<void>{if(this.saving())return;this.saving.set(true);try{await this.api.inviteMember({body:{...mutation(),email:this.email,role:this.role}});this.dialog.close(true);}catch(error:unknown){this.error.set(errorMessage(error));}finally{this.saving.set(false);}}
