@Component({selector:'app-competitor-dialog',imports:[FormsModule,IconComponent,ReferencePickerComponent],template:`

  <header class="dialog-head"><div><h2>{{data.observation?'Исправить наблюдение':'Добавить наблюдение'}}</h2><p>Наличие, цена и сопоставимые условия сохраняются раздельно.</p></div><button class="icon-button" (click)="dialog.close()" aria-label="Закрыть"><app-icon name="close" /></button></header>
  <form #observationForm="ngForm" (ngSubmit)="save()"><div class="dialog-body">
    @if(error()){<div class="notice error" role="alert">{{error()}}</div>}
    <app-reference-picker kind="offers" label="Наш товар" [(value)]="offerId" [disabled]="!!data.observation" />
    @if(!data.observation){
      <label class="field">Источник наблюдения<select name="sourceMode" [(ngModel)]="sourceMode"><option value="new">Новый источник</option><option value="existing">Из сохранённых источников</option></select></label>
      @if(sourceMode==='existing'){
        <div class="fields-2"><label class="field">Поиск продавца<input name="sourceSearch" [(ngModel)]="sourceSearch" maxlength="200"></label><button class="btn" type="button" [disabled]="sourcesLoading()" (click)="searchSources()">Найти источник</button></div>
        @if(sourceError()){<div class="notice error" role="alert">{{sourceError()}}<button class="btn" type="button" (click)="loadSources()">Повторить</button></div>}
        <label class="field">Продавец и источник<select name="sourceId" [(ngModel)]="selectedSourceId" (ngModelChange)="selectSource($event)" required><option value="">Выберите источник</option>@for(source of sources();track source.sourceId){<option [value]="source.sourceId">{{source.sellerName}} · {{source.sourceId}}</option>}</select></label>
        <div class="pagination"><span>{{sourceTotal()}} источников</span><button type="button" class="btn" [disabled]="sourcesLoading()||sourcePage()===0" (click)="sourcePage.set(sourcePage()-1);loadSources()">Назад</button><button type="button" class="btn" [disabled]="sourcesLoading()||(sourcePage()+1)*50>=sourceTotal()" (click)="sourcePage.set(sourcePage()+1);loadSources()">Далее</button></div>
      }
    }
    <label class="field">Продавец<input name="seller" [(ngModel)]="sellerName" required maxlength="200"></label>
    <label class="field">Сопоставимые условия<textarea name="segment" [(ngModel)]="segment" required maxlength="1000"></textarea><small>Точная идентичность сегмента площадки: комплект, состояние товара, регион, условия доставки и оплаты. Тот же сегмент нужен в конкурентном правиле.</small></label>
    <div class="fields-2"><label class="field">Цена, ₽<input name="price" [(ngModel)]="price" inputmode="decimal"><small>Пусто — цена неизвестна.</small></label><label class="field">Стоимость доставки, ₽<input name="delivery" [(ngModel)]="delivery" inputmode="decimal"><small>Явный 0 — бесплатно; пусто — неизвестна.</small></label></div>
    <label class="field">Наличие<select name="inStock" [(ngModel)]="inStock"><option value="unknown">Неизвестно</option><option value="yes">Есть в наличии</option><option value="no">Нет в наличии</option></select></label>
    <label class="field">Наблюдалось<input name="observed" [(ngModel)]="observedAt" type="datetime-local" [readOnly]="!!data.observation" required><small>Исправление не освежает время наблюдения.</small></label>
    <label class="option-line"><input name="ownOffer" [(ngModel)]="ownOffer" type="checkbox">Наше собственное предложение</label>
    <p class="inline-note">Отзыв, неизвестное наличие или доставка не заменяются пригодной ценой. Актуальность и пригодность ориентира проверяет расчёт.</p>
  </div><footer class="dialog-footer">@if(data.observation&&!data.observation.revoked&&context.allows('competitor.write')){<button class="btn danger" type="button" [disabled]="saving()" (click)="revoke()">Отозвать наблюдение</button>}<span class="spacer"></span><button type="button" class="btn" (click)="dialog.close()">Отмена</button><button type="submit" class="btn primary" [disabled]="saving()||observationForm.invalid||!offerId||!context.allows('competitor.write')">Сохранить наблюдение</button></footer></form>
`})

export class CompetitorDialogComponent extends GuardedFormDialog {
  readonly context=inject(ContextService);
  readonly data=inject<{observation?:CompetitorObservation}>(MAT_DIALOG_DATA);
  readonly dialog=inject(MatDialogRef<CompetitorDialogComponent>);
  private readonly api=inject(ApiService);private readonly dialogs=inject(MatDialog);
  private readonly reads=new ViewRefresh(inject(DestroyRef));private epoch=0;
  readonly error=signal('');readonly saving=signal(false);readonly sourceError=signal('');
  readonly sources=signal<CompetitorSource[]>([]);readonly sourcesLoading=signal(false);readonly sourcePage=signal(0);readonly sourceTotal=signal(0);
  offerId=this.data.observation?.offerId??'';sellerName=this.data.observation?.sellerName??'';
  private readonly newSourceId=crypto.randomUUID();sourceMode:'new'|'existing'='new';selectedSourceId='';sourceSearch='';
  segment=this.data.observation?.segment??'';price=this.data.observation?.price??'';delivery=this.data.observation?.delivery??'';
  inStock=this.data.observation?.inStock===true?'yes':this.data.observation?.inStock===false?'no':'unknown';
  ownOffer=this.data.observation?.ownOffer??false;
  observedAt=this.data.observation?localDateTime(this.data.observation.observedAt,this.context.account()?.timezone??'UTC'):'';
  constructor(){super();if(!this.data.observation)void this.loadSources();inject(DestroyRef).onDestroy(()=>this.epoch++);}
  searchSources():void{this.sourcePage.set(0);void this.loadSources();}
  loadSources():Promise<void>{this.epoch++;return this.reads.run('sources',async()=>{const epoch=++this.epoch;this.sourcesLoading.set(true);this.sourceError.set('');try{const result=await this.api.listCompetitorSources({query:{page:this.sourcePage(),size:50,search:this.sourceSearch}});if(epoch===this.epoch){this.sources.set(result.items);this.sourceTotal.set(result.total);}}catch(error:unknown){if(epoch===this.epoch)this.sourceError.set(errorMessage(error));}finally{if(epoch===this.epoch)this.sourcesLoading.set(false);}},()=>!this.sourceError());}
  selectSource(id:string):void{const selected=this.sources().find(source=>source.sourceId===id);if(selected)this.sellerName=selected.sellerName;}
  async revoke():Promise<void>{const observation=this.data.observation;if(!observation||this.saving())return;const confirmed=await firstValueFrom(this.dialogs.open(ConfirmDialogComponent,{width:'520px',data:{title:'Отозвать наблюдение?',message:'Оно останется в истории и перестанет участвовать в конкурентном ориентире.',action:'Отозвать',danger:true}}).afterClosed());if(!confirmed)return;this.saving.set(true);try{await this.api.revokeCompetitor({path:{id:observation.id},body:mutation(observation.revision)});this.dialog.close(true);}catch(error:unknown){this.error.set(errorMessage(error));}finally{this.saving.set(false);}}
  async save():Promise<void>{
    if(this.saving())return;this.saving.set(true);this.error.set('');
    try{const body={...mutation(this.data.observation?.revision),offerId:this.offerId,sourceId:this.data.observation?.sourceId??(this.sourceMode==='new'?this.newSourceId:this.selectedSourceId),sellerName:this.sellerName,segment:this.segment,price:this.price||null,delivery:this.delivery||null,observedAt:this.data.observation?.observedAt??accountInstant(this.observedAt,this.context.account()?.timezone??'UTC'),inStock:this.inStock==='unknown'?null:this.inStock==='yes',ownOffer:this.ownOffer};
      if(this.data.observation)await this.api.updateCompetitor({path:{id:this.data.observation.id},body});else await this.api.createCompetitor({body});this.dialog.close(true);
    }catch(error:unknown){this.error.set(errorMessage(error));}finally{this.saving.set(false);}
  }
}

@Component({selector:'app-filter-dialog',imports:[FormsModule,IconComponent,ReferencePickerComponent],template:`
  <header class="dialog-head"><div><h2>Фильтры</h2><p>Условия применяются ко всей разрешённой выборке.</p></div><button class="icon-button" (click)="dialog.close()" aria-label="Закрыть"><app-icon name="close" /></button></header>
  <form #filterForm="ngForm" (ngSubmit)="apply()"><div class="dialog-body"><div class="fields-2">@for(field of data.fields;track field.id){@if(field.type==='reference'&&field.reference){<app-reference-picker [kind]="field.reference" [label]="field.label" [value]="values[field.id]||''" (valueChange)="values[field.id]=$event" />}@else{<label class="field">{{field.label}}@if(field.type==='select'){<select [name]="field.id" [(ngModel)]="values[field.id]"><option value="">Все</option>@for(option of field.options;track option.value){<option [value]="option.value">{{option.label}}</option>}</select>}@else{<input [type]="field.type" [name]="field.id" [(ngModel)]="values[field.id]" [required]="field.required??false" maxlength="512">}</label>}}</div>@if(!data.fields.length){<p class="inline-note">Для этой выборки используйте поиск и сортировку таблицы.</p>}@if(error()){<p class="error-text" role="alert">{{error()}}</p>}</div><footer class="dialog-footer"><button class="btn quiet" type="button" (click)="reset()">Сбросить</button><span class="spacer"></span><button class="btn" type="button" (click)="dialog.close()">Отмена</button><button class="btn primary" type="submit" [disabled]="filterForm.invalid">Применить</button></footer></form>
`})
export class FilterDialogComponent {
  readonly data=inject<{filters:Record<string,string>;fields:FilterField[];defaults:Record<string,string>}>(MAT_DIALOG_DATA);readonly dialog=inject(MatDialogRef<FilterDialogComponent>);readonly error=signal('');values={...this.data.filters};
  reset():void{this.values={...this.data.defaults};}
  apply():void{const from=this.values['from'],to=this.values['to'];if(from&&to&&from>to){this.error.set('Дата окончания должна быть не раньше начала.');return;}const entries=Object.entries(this.values).filter(([,value])=>value!=='');if(entries.length>20){this.error.set('Допускается до 20 активных фильтров.');return;}const runFrom=this.values['runFrom'],runTo=this.values['runTo'];if(runFrom&&runTo&&runFrom>runTo){this.error.set('Конец периода расчётов должен быть не раньше начала.');return;}this.dialog.close(Object.fromEntries(entries));}
}

@Component({selector:'app-import-dialog',imports:[FormsModule,IconComponent],template:`
  <header class="dialog-head"><div><h2>Импорт данных</h2><p>Файл сначала проверяется. Применение потребует отдельного подтверждения.</p></div><button class="icon-button" (click)="dialog.close()" aria-label="Закрыть"><app-icon name="close" /></button></header><form (ngSubmit)="upload()"><div class="dialog-body">@if(error()){<div class="notice error" role="alert">{{error()}}</div>}<label class="field">Тип данных<select name="kind" [(ngModel)]="kind"><option value="COSTS">Себестоимость</option><option value="COMPETITORS">Наблюдения конкурентов</option><option value="SELLER_COSTS">Расходы продавца</option><option value="TAX">Налог</option><option value="PRICE_PARAMETERS">Параметры цен</option></select></label><p><a class="btn" [href]="templateUrl()">Скачать шаблон CSV</a></p><div class="fields-2"><label class="field">Разделитель CSV<select name="delimiter" [(ngModel)]="delimiter"><option value="SEMICOLON">Точка с запятой</option><option value="COMMA">Запятая</option></select></label><label class="field">Десятичный разделитель<select name="decimalSeparator" [(ngModel)]="decimalSeparator"><option value="DOT">Точка</option><option value="COMMA">Запятая</option></select></label></div><label class="field">Имя листа XLSX<input name="sheetName" [(ngModel)]="sheetName" maxlength="128"><small>Для книги с несколькими листами укажите нужный лист.</small></label><label class="dropzone"><app-icon name="upload" /><strong>Выберите файл CSV или XLSX</strong><input type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" (change)="pick($event)" required><small>Файл отправляется без загрузки всего содержимого в память страницы.</small></label>@if(file()){<p>{{file()?.name}}</p>}</div><footer class="dialog-footer"><button class="btn" type="button" (click)="dialog.close()">Отмена</button><button class="btn primary" type="submit" [disabled]="saving()||!file()">Загрузить для проверки</button></footer></form>
`})
export class ImportDialogComponent extends GuardedFormDialog {
  private readonly context=inject(ContextService);
  templateUrl():string{const scope=new URLSearchParams({organizationId:this.context.organization()?.id??'',accountId:this.context.account()?.id??''});return `/api/v1/imports/templates/${this.kind}?${scope.toString()}`;}
  readonly dialog=inject(MatDialogRef<ImportDialogComponent>);private readonly api=inject(ApiService);readonly error=signal('');readonly saving=signal(false);readonly file=signal<File|null>(null);kind:'COSTS'|'SELLER_COSTS'|'TAX'|'PRICE_PARAMETERS'|'COMPETITORS'='COSTS';delimiter:'SEMICOLON'|'COMMA'='SEMICOLON';decimalSeparator:'DOT'|'COMMA'='DOT';sheetName='';
  pick(event:Event):void{const target=event.target;if(target instanceof HTMLInputElement)this.file.set(target.files?.item(0)??null);}
  private uploadId=crypto.randomUUID();private uploadIntent='';private uploadFile?:File;
  async upload():Promise<void>{const file=this.file();if(!file||this.saving())return;const intent=JSON.stringify([this.kind,this.delimiter,this.decimalSeparator,this.sheetName]);if(this.uploadFile!==file||this.uploadIntent!==intent){this.uploadFile=file;this.uploadIntent=intent;this.uploadId=crypto.randomUUID();}this.saving.set(true);try{const operation=await this.api.uploadImport({body:{file,kind:this.kind,delimiter:this.delimiter,decimalSeparator:this.decimalSeparator,sheetName:this.sheetName||undefined,clientRequestId:this.uploadId,expectedRevision:0}});this.dialog.close(operation);}catch(error:unknown){this.error.set(errorMessage(error));}finally{this.saving.set(false);}}
}

@Component({selector:'app-confirm-dialog',imports:[IconComponent],template:`<header class="dialog-head"><h2>{{data.title}}</h2><button class="icon-button" aria-label="Закрыть" (click)="dialog.close(false)"><app-icon name="close" /></button></header><div class="dialog-body"><p>{{data.message}}</p></div><footer class="dialog-footer"><button class="btn" (click)="dialog.close(false)">Отмена</button><button [class]="data.danger?'btn danger':'btn primary'" (click)="dialog.close(true)">{{data.action}}</button></footer>`})
export class ConfirmDialogComponent {readonly data=inject<{title:string;message:string;action:string;danger?:boolean}>(MAT_DIALOG_DATA);readonly dialog=inject(MatDialogRef<ConfirmDialogComponent>);}

@Component({selector:'app-detail-dialog',imports:[IconComponent],template:`<header class="dialog-head"><div><h2>{{data.title}}</h2><p>{{data.subtitle}}</p></div><button class="icon-button" aria-label="Закрыть" (click)="dialog.close()"><app-icon name="close" /></button></header><div class="dialog-body">@for(row of data.rows;track $index){<div class="data-pair"><span>{{row.label}}</span><strong>{{row.value}}</strong></div>}@if(data.note){<p class="inline-note">{{data.note}}</p>}@if(data.downloadUrl){<a class="btn primary" [href]="data.downloadUrl">Скачать файл</a>}</div><footer class="dialog-footer"><button class="btn" (click)="dialog.close()">Закрыть</button></footer>`})
export class DetailDialogComponent {readonly data=inject<{title:string;subtitle?:string;rows:{label:string;value:string}[];note?:string;downloadUrl?:string}>(MAT_DIALOG_DATA);readonly dialog=inject(MatDialogRef<DetailDialogComponent>);}
